use axbi_background_table_benchmark::*;
use rei_microphysics::axbi_background::{BackgroundFamily,BackgroundPoint};
use std::{fs,io::{Write,BufWriter},hint::black_box,time::Instant,path::PathBuf};
fn cpu()->f64{let s=fs::read_to_string("/proc/self/schedstat").unwrap();s.split_whitespace().next().unwrap().parse::<f64>().unwrap()/1e9}
fn check(ok:bool,gate:&str,case:usize,n:usize,a:f64,reference:f64,candidate:f64)->Result<(),String>{if ok{Ok(())}else{Err(format!("{{\"gate\":\"{gate}\",\"case\":{case},\"n\":{n},\"a\":{a:e},\"a_bits\":{},\"reference\":{reference:e},\"candidate\":{candidate:e}}}",a.to_bits()))}}
fn main(){if let Err(e)=run(){eprintln!("{e}");std::process::exit(2)}}
fn run()->Result<(),String>{
 let args:Vec<_>=std::env::args().collect();if args.len()!=5||args[1]!="--contract"||args[3]!="--output"{return Err("expected --contract PATH --output PATH".into())}
 let contract=fs::read_to_string(&args[2]).map_err(|e|e.to_string())?;if contract!=include_str!("../AUTHORITY_CONTRACT.json"){return Err("IMMUTABLE_CONTRACT_MISMATCH".into())}
 let out=PathBuf::from(&args[4]);let parent=out.parent().unwrap();let mut raw=BufWriter::new(fs::File::create(parent.join("numeric.jsonl")).map_err(|e|e.to_string())?);
 let counts=Counts::default();let contract_parent=PathBuf::from(&args[2]).parent().unwrap().to_path_buf();let count_bytes=fs::read_to_string(contract_parent.join("raw/local_test_counts.json")).map_err(|e|format!("missing measured local test counts: {e}"))?;let body=count_bytes.trim().strip_prefix('{').and_then(|s|s.strip_suffix('}')).ok_or("malformed counts object")?;let mut values=[None;3];for pair in body.split(','){let(k,v)=pair.split_once(':').ok_or("malformed counts field")?;let idx=match k.trim(){"\"direct\""=>0,"\"candidate\""=>1,"\"integrand\""=>2,_=>return Err("unknown counts field".into())};if values[idx].is_some(){return Err("duplicate counts field".into())}values[idx]=Some(v.trim().parse::<u64>().map_err(|_|"invalid counts integer")?);}let local:[u64;3]=[values[0].ok_or("missing direct")?,values[1].ok_or("missing candidate")?,values[2].ok_or("missing integrand")?];if local[0]>65536-58500||local[1]>8000000-400000||local[2]>2000000-60000{return Err("insufficient remaining cumulative quota for fixed matrix".into())}counts.direct.set(local[0]);counts.candidate.set(local[1]);counts.integrand.set(local[2]);
 let result=matrix(&counts,&mut raw);raw.flush().map_err(|e|e.to_string())?;
 let (status,detail)=match &result{Ok(hold)=>(if *hold{"COMPONENT_GATES_PASS_SHORT_STEP_SUBTRACTION_HOLD"}else{"COMPONENT_GATES_PASS"},"null".to_string()),Err(e)=>("FIRST_CORE_FAILURE",e.clone())};
 fs::write(&out,format!("{{\"status\":\"{status}\",\"first_failure\":{detail},\"direct_calls_cumulative\":{},\"cache_table_queries_cumulative\":{},\"local_integrand_evaluations_cumulative\":{},\"trajectory_starts\":0,\"scientific_admission\":\"NOT_ISSUED\"}}\n",counts.direct.get(),counts.candidate.get(),counts.integrand.get())).map_err(|e|e.to_string())?; result.map(|_|())
}
fn matrix(counts:&Counts,raw:&mut impl Write)->Result<bool,String>{
 let mut hold=false;let mut reflection:Vec<Vec<BackgroundPoint>>=Vec::new();let span=(AE/AR).ln();
 for (ci,(q,family)) in [(0.0,BackgroundFamily::PhysicalDensityFixed),(0.005,BackgroundFamily::PhysicalDensityFixed),(-0.005,BackgroundFamily::PhysicalDensityFixed),(0.01,BackgroundFamily::PhysicalDensityFixed),(-0.01,BackgroundFamily::PhysicalDensityFixed),(0.01,BackgroundFamily::SameHDiagnostic)].into_iter().enumerate(){
  let m=Model::new(q,family,counts.clone()).map_err(|e|format!("{{\"error\":\"{e:?}\"}}"))?;
  let start=Instant::now();let cstart=cpu();let refs:Vec<_>=(0..=8192).map(|j|m.direct(scale(j,8192)).unwrap()).collect();let construction_wall=start.elapsed().as_secs_f64();let construction_cpu=cpu()-cstart;
  if ci==2||ci==4{let positive=&reflection[ci-1];for (j,(p,r)) in refs.iter().zip(positive).enumerate(){for (name,x,y) in [("reflection_H",p.h_per_s,r.h_per_s),("reflection_t",p.time_s,r.time_s),("reflection_b",p.b,-r.b),("reflection_s",p.s_per_s,-r.s_per_s)]{check((x-y).abs()<=1e-12*x.abs().max(y.abs()).max(f64::MIN_POSITIVE),name,ci,0,scale(j,8192),y,x)?;}}}
  reflection.push(refs.clone());let mut assembly=Vec::new();let mut levels=Vec::new();for n in [1024,2048]{let start=Instant::now();let cp=cpu();let table=Table::from_reference(m.clone(),&refs,n);let wall=start.elapsed().as_secs_f64();let cpu_s=cpu()-cp;assembly.push((wall,cpu_s));levels.push(table);writeln!(raw,"{{\"kind\":\"table_assembly\",\"case\":{ci},\"n\":{n},\"wall_s\":{wall:e},\"cpu_s\":{cpu_s:e}}}").unwrap();}let tables=levels;let mut difference=[0.0_f64;3];for r in &refs{let p=tables[0].query(r.a).unwrap();let q=tables[1].query(r.a).unwrap();difference[0]=difference[0].max((p.time_s-q.time_s).abs());difference[1]=difference[1].max((p.time_s-q.time_s).abs()/r.time_s.abs().max(1.0));difference[2]=difference[2].max((p.b-q.b).abs());}writeln!(raw,"{{\"kind\":\"level_difference\",\"case\":{ci},\"clock_abs_s\":{:e},\"clock_normalized\":{:e},\"b_abs\":{:e},\"shared_total_construction_wall_s\":{:e},\"shared_total_construction_cpu_s\":{:e}}}",difference[0],difference[1],difference[2],construction_wall+assembly.iter().map(|x|x.0).sum::<f64>(),construction_cpu+assembly.iter().map(|x|x.1).sum::<f64>()).unwrap();
  writeln!(raw,"{{\"kind\":\"construction\",\"case\":{ci},\"shared_reference_grid_wall_s\":{construction_wall},\"shared_reference_grid_cpu_s\":{construction_cpu},\"reference_points\":8193}}").unwrap();
  for t in &tables{let n=t.knots.len()-1;let mut last=-1.0;let(mut et,mut eb,mut edt,mut edb)=(0.0_f64,0.0_f64,0.0_f64,0.0_f64);
   for j in 0..=n*4{let r=refs[j*(8192/(n*4))];let p=t.query(r.a).unwrap();let(dt,db)=t.derivatives(r.a).unwrap();let terr=(p.time_s-r.time_s).abs()/r.time_s.abs().max(1.0);let berr=(p.b-r.b).abs();let dterr=(dt*r.h_per_s-1.0).abs();let dberr=(db-r.sigma).abs();et=et.max(terr);eb=eb.max(berr);edt=edt.max(dterr);edb=edb.max(dberr);
    check(point_bits(p)[0]==r.a.to_bits(),"supplied_a",ci,n,r.a,r.a,p.a)?;check(terr<=1e-9,"clock",ci,n,r.a,r.time_s,p.time_s)?;check(berr<=1e-11,"b",ci,n,r.a,r.b,p.b)?;check(dterr<=1e-9,"clock_derivative",ci,n,r.a,1.0/r.h_per_s,dt)?;check(dberr<=1e-11,"b_derivative",ci,n,r.a,r.sigma,db)?;
    check(p.time_s.is_finite()&&p.time_s>last&&p.h_per_s.is_finite()&&p.h_per_s>0.0,"monotonic_finite",ci,n,r.a,last,p.time_s)?;last=p.time_s;
    check(point_bits(p)[3..]==point_bits(r)[3..],"algebraic_bits",ci,n,r.a,r.h_per_s,p.h_per_s)?;
    if j%4==0 {check(p.time_s.to_bits()==r.time_s.to_bits()&&p.b.to_bits()==r.b.to_bits(),"exact_knot",ci,n,r.a,r.time_s,p.time_s)?;}
    if q==0.0{check(p.b==0.0&&p.sigma==0.0&&p.s_per_s==0.0,"zero_shear",ci,n,r.a,0.0,p.b)?;}
   }
   for a in [f64::NAN,f64::INFINITY,0.0,-1.0,AR*0.999,AE*1.001]{check(t.query(a).is_err(),"domain_error",ci,n,AR,0.0,0.0)?;}
   writeln!(raw,"{{\"kind\":\"point_errors\",\"case\":{ci},\"n\":{n},\"max_clock_rel\":{et:e},\"max_b_abs\":{eb:e},\"max_clock_derivative_rel\":{edt:e},\"max_b_derivative_abs\":{edb:e}}}").unwrap();
  }
  // At most 90 distinct intervals per case; both levels use identical intervals.
  for anchor in 0..=8{for dl in [1e-10,1e-8,1e-6,0.0001,0.005]{let l=span*anchor as f64/8.0;let pair=if l+dl<=span{(l,l+dl)}else{(l-dl,l)};let knot=(l/tables[1].h).round()*tables[1].h;let mut pairs=vec![pair];if knot-dl/2.0>=0.0&&knot+dl/2.0<=span{pairs.push((knot-dl/2.0,knot+dl/2.0));}
   for (l1,l2) in pairs{let a1=if l1==0.0{AR}else{AR*l1.exp()};let a2=if l2==span{AE}else{AR*l2.exp()};let r32=m.local_integral(a1,a2,32).unwrap();let r64=m.local_integral(a1,a2,64).unwrap();check((r32/r64-1.0).abs()<=1e-9,"local_quadrature",ci,0,a1,r64,r32)?;let d=m.direct(a2).unwrap().time_s-m.direct(a1).unwrap().time_s;
    for t in &tables{let stable=t.increment(a1,a2).unwrap();let actual=t.query(a2).unwrap().time_s-t.query(a1).unwrap().time_s;let stable_error=(stable/r64-1.0).abs();let actual_error=(actual/r64-1.0).abs();let direct_error=(d/r64-1.0).abs();check(stable>0.0&&stable_error<=1e-9,"stable_increment",ci,t.knots.len()-1,a1,r64,stable)?;let limited=actual_error>1e-8||direct_error>1e-8;hold|=limited;
    writeln!(raw,"{{\"kind\":\"interval\",\"case\":{ci},\"n\":{},\"a1_bits\":{},\"a2_bits\":{},\"nominal_requested_dL\":{:e},\"actual_delta_L\":{:e},\"reference64_s\":{r64:e},\"reference32_s\":{r32:e},\"stable_s\":{stable:e},\"table_subtraction_s\":{actual:e},\"direct_subtraction_s\":{d:e},\"stable_relative_error\":{stable_error:e},\"table_subtraction_relative_error\":{actual_error:e},\"direct_subtraction_relative_error\":{direct_error:e},\"short_step_hold\":{limited}}}",t.knots.len()-1,a1.to_bits(),a2.to_bits(),dl,((a2-a1)/a1).ln_1p()).unwrap();}
   }
  }}
  for pattern in ["repeated","unique"]{let queries:Vec<_>=(0..128).map(|j|if pattern=="repeated"{scale(j%16,16)}else{scale(j,127)}).collect();writeln!(raw,"{{\"kind\":\"query_bits\",\"case\":{ci},\"pattern\":\"{pattern}\",\"bits\":{:?}}}",queries.iter().map(|a|a.to_bits()).collect::<Vec<_>>()).unwrap();
   for rep in 0..3{let mut cache=ExactCache::new(m.clone());for mode in 0..4{let start=Instant::now();let cp=cpu();let mut checksum=0.0;for &a in &queries{let p=match mode{0=>m.direct(black_box(a)),1=>cache.query(black_box(a)),2=>tables[0].query(black_box(a)),_=>tables[1].query(black_box(a))}.unwrap();checksum+=black_box(p.time_s+p.b+p.h_per_s+p.s_per_s);}let wall=start.elapsed().as_secs_f64();let cpu_s=cpu()-cp;black_box(checksum);writeln!(raw,"{{\"kind\":\"timing\",\"case\":{ci},\"pattern\":\"{pattern}\",\"rep\":{rep},\"mode\":{mode},\"queries\":128,\"wall_s\":{wall:e},\"cpu_s\":{cpu_s:e},\"checksum\":{checksum:e},\"cache_hits\":{},\"cache_misses\":{}}}",cache.hits,cache.misses).unwrap();}}
  }
 }
 Ok(hold)
}
